-- =====================================================================
-- 02_key_attributes.sql — the register: 22 key attributes, their rules in SHADOW, and the five source tables selected.
-- Copied from sql/migrate_key_attributes.py's output. On a fresh schema parts 1-3
-- retire nothing (there is no mock register here) and their INSERTs add 0 rows.
-- Re-runnable: every INSERT is guarded.
-- =====================================================================

-- =====================================================================
-- migrate_key_attributes.sql — GENERATED by sql/migrate_key_attributes.py. Do not edit.
-- target: sdpt_data_trnf.udp_brnz, prefix dq_
--
-- Retires the mock register (every element, rule and monitored table that is
-- not a key attribute), then registers the 22 key attributes from
-- DQ_ATTR_PRIORI.xlsx and their 119 migration rules, all in SHADOW, and
-- selects their five prod.* source tables. Re-running inserts nothing.
-- See the generator's docstring.
-- =====================================================================

-- Step 0 — before. EXPECTED: the mock register's counts, and 0 key attributes.

SELECT CASE WHEN cde_id LIKE 'KA\\_%' THEN 'key attribute' ELSE 'mock' END AS kind,
       status, COUNT(*) AS elements
FROM   sdpt_data_trnf.udp_brnz.dq_config_v_cde_registry_current
GROUP  BY 1, 2 ORDER BY 1, 2;

SELECT status, COUNT(*) AS rules FROM sdpt_data_trnf.udp_brnz.dq_config_v_rule_registry_current GROUP BY status ORDER BY status;

SELECT target_table, table_version, status FROM sdpt_data_trnf.udp_brnz.dq_config_v_monitored_table_current ORDER BY target_table;

-- =====================================================================
-- Part 1 — retire every element that is not a key attribute
-- =====================================================================

INSERT INTO sdpt_data_trnf.udp_brnz.dq_config_cde_registry (cde_id, cde_version, cde_name, business_term, data_class, definition, expected_signature, criticality, pii, regulatory_basis, tolerance_pct, bindings, business_domain, owner_group, status, effective_from, registered_by, registered_at, note)
SELECT c.cde_id, c.cde_version + 1, c.cde_name, c.business_term, c.data_class, c.definition, c.expected_signature, c.criticality, c.pii, c.regulatory_basis, c.tolerance_pct, c.bindings, c.business_domain, c.owner_group, 'retired', current_timestamp(), current_user(), current_timestamp(), 'Retired 2026-10-12 with the rest of the mock register: the register is now the key attributes from DQ_ATTR_PRIORI.xlsx. Runs and problems before this date stand as history.'
FROM   sdpt_data_trnf.udp_brnz.dq_config_cde_registry c
JOIN   (SELECT cde_id AS id, max(cde_version) AS v FROM sdpt_data_trnf.udp_brnz.dq_config_cde_registry GROUP BY cde_id) m
  ON   m.id = c.cde_id AND m.v = c.cde_version
WHERE  c.status <> 'retired' AND c.cde_id NOT LIKE 'KA\\_%';

-- =====================================================================
-- Part 2 — retire every rule that does not name a key attribute
-- =====================================================================

INSERT INTO sdpt_data_trnf.udp_brnz.dq_config_rule_registry (rule_id, rule_version, rule_name, target_table, target_column, cde_id, rule_type, rule_expr, scope_filter, join_sql, fail_threshold_pct, severity, business_domain, owner_group, source_layer, status, effective_from, created_by, created_at, promoted_by, promoted_at, note)
SELECT r.rule_id, r.rule_version + 1, r.rule_name, r.target_table, r.target_column, r.cde_id, r.rule_type, r.rule_expr, r.scope_filter, r.join_sql, r.fail_threshold_pct, r.severity, r.business_domain, r.owner_group, r.source_layer, 'retired', current_timestamp(), current_user(), current_timestamp(), r.promoted_by, r.promoted_at, 'Retired 2026-10-12: its element was mock data, retired with the rest of the mock register in favour of the key attributes and their migration rules.'
FROM   sdpt_data_trnf.udp_brnz.dq_config_rule_registry r
JOIN   (SELECT rule_id AS id, max(rule_version) AS v FROM sdpt_data_trnf.udp_brnz.dq_config_rule_registry GROUP BY rule_id) m
  ON   m.id = r.rule_id AND m.v = r.rule_version
WHERE  r.status <> 'retired' AND coalesce(r.cde_id, '') NOT LIKE 'KA\\_%';

-- =====================================================================
-- Part 3 — decommission every monitored table holding no key attribute
-- =====================================================================

-- The slice in force carries forward; a pending proposal only while pending
-- (dq_app/domain/slices.carry_forward says the same).
INSERT INTO sdpt_data_trnf.udp_brnz.dq_config_monitored_table (target_table, table_version, table_code, row_key, owner_group, business_domain, schedule_group, scan_mode, status, effective_from, selected_by, note, slice_filter, slice_spec, slice_version, slice_change, slice_proposed_filter, slice_proposed_spec, slice_proposed_by)
SELECT t.target_table, t.table_version + 1, t.table_code, t.row_key, t.owner_group, t.business_domain, t.schedule_group, t.scan_mode, 'retired', current_timestamp(), current_user(), 'Decommissioned 2026-10-12: it holds no key attribute. The register moved off the mock data to the key attributes from DQ_ATTR_PRIORI.xlsx.', t.slice_filter, t.slice_spec, t.slice_version, CAST(NULL AS STRING), CASE WHEN (t.slice_proposed_by IS NOT NULL AND coalesce(t.slice_change, '') NOT IN ('approved', 'rejected')) THEN t.slice_proposed_filter END, CASE WHEN (t.slice_proposed_by IS NOT NULL AND coalesce(t.slice_change, '') NOT IN ('approved', 'rejected')) THEN t.slice_proposed_spec END, CASE WHEN (t.slice_proposed_by IS NOT NULL AND coalesce(t.slice_change, '') NOT IN ('approved', 'rejected')) THEN t.slice_proposed_by END
FROM   sdpt_data_trnf.udp_brnz.dq_config_monitored_table t
JOIN   (SELECT target_table AS id, max(table_version) AS v FROM sdpt_data_trnf.udp_brnz.dq_config_monitored_table GROUP BY target_table) m
  ON   m.id = t.target_table AND m.v = t.table_version
WHERE  t.status <> 'retired' AND t.target_table NOT IN ('prod.udp_brnz_nrt_tech_view.table_address_hist', 'prod.udp_brnz_nrt_tech_view.table_bus_org_hist', 'prod.udp_brnz_nrt_tech_view.table_contact_hist', 'prod.udp_brnz_nrt_tech_view.table_contact_role_hist', 'prod.udp_brnz_nrt_tech_view.table_customer_hist');

