-- =====================================================================
-- Part 7 — verification, read-only
-- =====================================================================

-- 7a — EXPECTED: one row, key attribute / registered / 22.
-- (The current view drops nothing: a retired element shows as retired here.)
SELECT CASE WHEN cde_id LIKE 'KA\\_%' THEN 'key attribute' ELSE 'mock' END AS kind,
       status, COUNT(*) AS elements
FROM   sdpt_data_trnf.udp_brnz.dq_config_v_cde_registry_current
GROUP  BY 1, 2 ORDER BY 1, 2;

-- 7b — EXPECTED: shadow 119, every one on a key attribute; nothing active;
-- the rest retired.
SELECT status, COUNT(*) AS rules,
       SUM(CASE WHEN cde_id LIKE 'KA\\_%' THEN 1 ELSE 0 END) AS on_key_attributes
FROM   sdpt_data_trnf.udp_brnz.dq_config_v_rule_registry_current GROUP BY status ORDER BY status;

-- 7c — EXPECTED: zero rows. Every live rule names a key attribute binding its column.
SELECT r.rule_id
FROM   sdpt_data_trnf.udp_brnz.dq_config_v_rule_registry_current r
LEFT JOIN (SELECT c.cde_id, b.target_table, b.target_column
           FROM sdpt_data_trnf.udp_brnz.dq_config_v_cde_registry_current c LATERAL VIEW explode(c.bindings) x AS b
           WHERE c.status = 'registered' AND b.binding_status = 'bound') e
  ON  e.cde_id = r.cde_id AND e.target_table = r.target_table
  AND e.target_column = r.target_column
WHERE r.status <> 'retired' AND e.cde_id IS NULL;

-- 7d — EXPECTED: the 5 prod.* tables selected, every other table retired.
SELECT target_table, table_version, status FROM sdpt_data_trnf.udp_brnz.dq_config_v_monitored_table_current ORDER BY status, target_table;

-- 7e — EXPECTED: no_rule 22. Shadow rules do not count as coverage;
-- a binding reads covered once its rules are promoted.
SELECT coverage_gap, COUNT(*) AS bindings FROM sdpt_data_trnf.udp_brnz.dq_results_v_cde_coverage GROUP BY coverage_gap ORDER BY 1;
